package com.autocare.platform.order;
import com.autocare.platform.vehicle.VehicleOwner;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.*;
import com.fasterxml.jackson.databind.JsonNode;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import static com.autocare.platform.order.ReservationStore.*;

/** Caller transactions own coupon transitions and their audit; never call external providers. */
public class CouponTransactions {
 public static final String CASH_RULE="R5B_CASH_V1",SERVICE_RULE="R5B_SERVICE_V1";
 final ReservationStore db;
 public CouponTransactions(ReservationStore db){this.db=db;}
 static ResponseStatusException conflict(){return new ResponseStatusException(HttpStatus.CONFLICT,"券资格、冻结或交易事实已变化，请重新核对");}
 static final String OWN="SELECT u.*,u.id AS user_coupon_id,i.publication_revision,p.terms_json,c.merchant_id,s.project_id,s.merchant_id AS source_merchant_id,c.is_deleted AS coupon_deleted,c.status AS coupon_status FROM user_coupon u LEFT JOIN coupon_issue i ON i.user_coupon_id=u.id AND i.user_id=u.user_id AND i.coupon_id=u.coupon_id LEFT JOIN coupon_publication p ON p.coupon_id=i.coupon_id AND p.revision=i.publication_revision LEFT JOIN coupon_source s ON s.coupon_id=i.coupon_id LEFT JOIN coupon c ON c.id=u.coupon_id";
 static Map<String,Object> own(ReservationStore db,long owner,long uc,boolean lock){return db.one(OWN+" WHERE u.id=? AND u.user_id=? AND u.is_deleted=0"+(lock?" FOR UPDATE":""),uc,owner);}
 static boolean known(ReservationStore db,Map<String,Object> r){try{var terms=db.parse(r.get("terms_json"));CouponInput.terms(terms);return r.get("publication_revision")!=null&&r.get("merchant_id")!=null&&Objects.equals(r.get("merchant_id"),r.get("source_merchant_id"))&&number(r,"project_id")==terms.get("project_id").longValue()&&number(r,"coupon_deleted")==0&&Set.of("PUBLISHED","STOPPED").contains(r.get("coupon_status"));}catch(RuntimeException invalid){return false;}}
 static String eligibility(ReservationStore db,Map<String,Object> r,long shop,long project,BigDecimal price,String type){
  if(!known(db,r))return "SOURCE_UNKNOWN";var terms=db.parse(r.get("terms_json"));
  if(!type.equals(terms.path("type").asText()))return type.equals("DISCOUNT")?"SERVICE_ONLY":"DISCOUNT_ONLY";
  if(!"AVAILABLE".equals(r.get("status"))||r.get("order_id")!=null)return "NOT_AVAILABLE";
  if(CouponInput.time(terms.get("valid_from")).isAfter(db.now()))return "NOT_STARTED";
  if(!CouponInput.time(terms.get("valid_to")).isAfter(db.now()))return "EXPIRED";
  if(number(r,"merchant_id")!=shop||number(r,"project_id")!=project)return "WRONG_SCOPE";
  if(db.jdbc.queryForObject("SELECT COUNT(*) FROM merchant WHERE id=? AND status=1 AND is_deleted=0",Long.class,shop)!=1L)return "ISSUER_UNAVAILABLE";
  if(db.jdbc.queryForObject("SELECT COUNT(*) FROM standard_project sp JOIN merchant_project mp ON mp.project_id=sp.id WHERE sp.id=? AND sp.status=1 AND sp.is_deleted=0 AND mp.merchant_id=? AND mp.on_shelf=1 AND mp.is_deleted=0",Long.class,project,shop)!=1L)return "PROJECT_UNAVAILABLE";
  if(type.equals("DISCOUNT")){if(price.compareTo(CouponInput.money(terms.get("min_spend")))<0)return "BELOW_MINIMUM";if(price.subtract(CouponInput.money(terms.get("amount"))).compareTo(new BigDecimal("0.01"))<0)return "ZERO_CASH";}
  return "ELIGIBLE";
 }
 Map<String,Object> candidate(Map<String,Object> r,Map<String,Object> q){boolean known=known(db,r);String why=eligibility(db,r,number(q,"merchant_id"),number(q,"project_id"),(BigDecimal)q.get("price"),"DISCOUNT");var out=new LinkedHashMap<String,Object>();out.put("user_coupon_id",number(r,"user_coupon_id"));out.put("coupon_id",number(r,"coupon_id"));out.put("source_known",known);out.put("merchant_id",known?r.get("merchant_id"):null);out.put("publication_revision",known?r.get("publication_revision"):null);out.put("terms",known?db.parse(r.get("terms_json")):null);out.put("eligibility",why);out.put("discount_amount",why.equals("ELIGIBLE")?db.parse(r.get("terms_json")).get("amount").textValue():null);out.put("cash_amount",why.equals("ELIGIBLE")?((BigDecimal)q.get("price")).subtract(CouponInput.money(db.parse(r.get("terms_json")).get("amount"))).toPlainString():null);return out;}
 public Map<String,Object> preview(VehicleOwner owner,JsonNode body){var b=CouponOrderInput.booking(body);int page=body.get("page").intValue();return db.reads.execute(tx->{db.owner(owner,false);var q=db.quote(b.quote(),false);if(number(q,"version_id")!=b.version())throw new ReservationConflict(40901,"报价已更新，请重新确认");var vehicle=db.one("SELECT id,model_id FROM vehicle WHERE id=? AND user_id=? AND is_deleted=0",b.vehicle(),owner.id());var slot=db.one("SELECT * FROM appointment_slot WHERE id=? AND merchant_id=? AND project_id=? AND is_deleted=0",b.slot(),q.get("merchant_id"),q.get("project_id"));var now=db.now();boolean open=number(slot,"is_open")==1&&instant(slot.get("starts_at")).isAfter(now);var slotView=db.slotRow(slot,now);long count=db.jdbc.queryForObject("SELECT COUNT(*) FROM user_coupon WHERE user_id=? AND is_deleted=0",Long.class,owner.id());var rows=db.jdbc.queryForList(OWN+" WHERE u.user_id=? AND u.is_deleted=0 ORDER BY u.id DESC LIMIT 20 OFFSET ?",owner.id(),(page-1)*20);Map<String,Object> selected=body.get("selected_user_coupon_id").isNull()?null:candidate(own(db,owner.id(),body.get("selected_user_coupon_id").longValue(),false),q);var out=new LinkedHashMap<String,Object>();out.put("quote",db.quoteResult(q));out.put("vehicle_id",number(vehicle,"id"));out.put("slot",slotView);out.put("coupons",page(rows.stream().map(r->candidate(r,q)).toList(),count,page,20));out.put("selected",selected);out.put("can_create",open&&((Number)slotView.get("capacity_left")).longValue()>0&&selected!=null&&selected.get("eligibility").equals("ELIGIBLE"));out.put("rule_version",CASH_RULE);return out;});}
 record Selection(Map<String,Object> coupon,JsonNode terms,BigDecimal cash,Instant validTo){}
 static String creationDigest(CouponOrderInput.Booking b){var i=b.booking();return com.autocare.platform.gateway.identity.AuthTokens.sha256(i.quote()+":"+i.version()+":"+i.vehicle()+":"+i.slot()+":"+b.coupon()+":"+b.publication()+":"+b.rule());}
 static com.autocare.platform.common.write.WriteIntegrityService.Change creationReplay(ReservationStore db,long owner,String key,CouponOrderInput.Booking b){
  // Immutable intent fields can be read without reversing the merchant/slot/order lock order.
  var rows=db.jdbc.queryForList("SELECT order_id,request_digest FROM order_coupon_allocation WHERE user_id=? AND creation_key=?",owner,com.autocare.platform.common.write.WriteIntegrityService.normalizeKey(key));
  if(rows.isEmpty())return null;var a=rows.get(0);if(!creationDigest(b).equals(a.get("request_digest")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"同一创建编号不能用于不同用券预约");
  var o=db.one("SELECT * FROM `order` WHERE id=? AND user_id=? AND is_deleted=0",a.get("order_id"),owner);
  var receipt=Map.<String,Object>of("order_id",number(o,"id"),"order_no",o.get("order_no"),"amount_due",o.get("pay_amount").toString(),"status","PENDING_PAYMENT","expires_at",iso(o.get("expires_at")));
  var same=Map.<String,Object>of("order_id",number(o,"id"));return new com.autocare.platform.common.write.WriteIntegrityService.Change("ORDER_COUPON_CREATION_REPLAY","order",number(o,"id"),same,same,receipt,false);
 }
 static Selection prepare(ReservationStore db,long owner,CouponOrderInput.Booking input,Map<String,Object> q){var r=own(db,owner,input.coupon(),true);if(!eligibility(db,r,number(q,"merchant_id"),number(q,"project_id"),(BigDecimal)q.get("price"),"DISCOUNT").equals("ELIGIBLE")||number(r,"publication_revision")!=input.publication())throw conflict();var terms=db.parse(r.get("terms_json"));return new Selection(r,terms,((BigDecimal)q.get("price")).subtract(CouponInput.money(terms.get("amount"))),CouponInput.time(terms.get("valid_to")));}
 static void reserve(ReservationStore db,long order,long owner,Selection selection,Instant deadline,String creationKey,CouponOrderInput.Booking input){var r=selection.coupon();var o=db.one("SELECT * FROM `order` WHERE id=? FOR UPDATE",order);db.jdbc.update("UPDATE `order` SET coupon_id=? WHERE id=?",r.get("coupon_id"),order);db.jdbc.update("INSERT INTO order_coupon_allocation(order_id,creation_key,request_digest,user_coupon_id,user_id,coupon_id,publication_revision,merchant_id,project_id,terms_json,original_amount,discount_amount,cash_amount,state,reserved_until,rule_version,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,'RESERVED',?,?,?,?)",order,com.autocare.platform.common.write.WriteIntegrityService.normalizeKey(creationKey),creationDigest(input),r.get("user_coupon_id"),owner,r.get("coupon_id"),r.get("publication_revision"),o.get("merchant_id"),o.get("project_id"),db.json(selection.terms()),o.get("amount"),CouponInput.money(selection.terms().get("amount")),selection.cash(),time(deadline),CASH_RULE,o.get("created_at"),time(db.now()));if(db.jdbc.update("UPDATE user_coupon SET status='RESERVED',order_id=?,reserved_until=?,used_at=NULL WHERE id=? AND user_id=? AND status='AVAILABLE' AND order_id IS NULL",order,time(deadline),r.get("user_coupon_id"),owner)!=1)throw conflict();event(db,number(r,"user_coupon_id"),"RESERVE","order:"+order+":reserve",order,null,null,null,"AVAILABLE","RESERVED",CASH_RULE);}
 static Map<String,Object> allocation(ReservationStore db,long order,boolean lock){var rows=db.jdbc.queryForList("SELECT * FROM order_coupon_allocation WHERE order_id=?"+(lock?" FOR UPDATE":""),order);return rows.isEmpty()?null:rows.get(0);}
 static boolean trustedOrder(ReservationStore db,Map<String,Object> o){var a=allocation(db,number(o,"id"),false);if(a==null)return false;try{var source=own(db,number(o,"user_id"),number(a,"user_coupon_id"),false);var t=db.parse(a.get("terms_json"));return CASH_RULE.equals(a.get("rule_version"))&&known(db,source)&&t.equals(db.parse(source.get("terms_json")))&&"DISCOUNT".equals(t.path("type").asText())&&Objects.equals(a.get("coupon_id"),o.get("coupon_id"))&&Objects.equals(a.get("user_id"),o.get("user_id"))&&Objects.equals(a.get("merchant_id"),o.get("merchant_id"))&&Objects.equals(a.get("project_id"),o.get("project_id"))&&Objects.equals(a.get("publication_revision"),source.get("publication_revision"))&&((BigDecimal)a.get("original_amount")).compareTo((BigDecimal)o.get("amount"))==0&&((BigDecimal)a.get("cash_amount")).compareTo((BigDecimal)o.get("pay_amount"))==0&&((BigDecimal)a.get("discount_amount")).compareTo(CouponInput.money(t.get("amount")))==0&&((BigDecimal)o.get("amount")).compareTo(CouponInput.money(t.get("min_spend")))>=0&&((BigDecimal)o.get("amount")).subtract((BigDecimal)a.get("discount_amount")).compareTo((BigDecimal)o.get("pay_amount"))==0&&((BigDecimal)o.get("pay_amount")).signum()>0;}catch(RuntimeException invalid){return false;}}
 static void event(ReservationStore db,long uc,String kind,String key,Long order,Long payment,Long refund,Long redemption,String before,String after,String rule){db.jdbc.update("INSERT INTO coupon_transaction_event(user_coupon_id,event_key,kind,order_id,payment_id,refund_id,redemption_id,before_status,after_status,rule_version,occurred_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",uc,key,kind,order,payment,refund,redemption,before,after,rule,time(db.now()));db.jdbc.update("INSERT INTO audit_log(actor_type,actor_id,action,resource_type,resource_id,before_state,after_state,request_id) VALUES('system',0,?,'user_coupon',?,?,?,?)","COUPON_"+kind,uc,db.json(Map.of("status",before)),db.json(Map.of("status",after,"event_key",key,"rule_version",rule)),UUID.randomUUID().toString());}
 static Map<String,Object> lockAllocation(ReservationStore db,long order){var meta=allocation(db,order,false);if(meta==null)return null;own(db,number(meta,"user_id"),number(meta,"user_coupon_id"),true);var a=allocation(db,order,true);if(!trustedOrder(db,db.one("SELECT * FROM `order` WHERE id=?",order)))throw conflict();return a;}
 static void consume(ReservationStore db,long order,long payment){var a=lockAllocation(db,order);if(a==null)return;String key="order:"+order+":consume";if(Set.of("CONSUMED","RETURNED").contains(a.get("state"))){if(db.jdbc.queryForObject("SELECT COUNT(*) FROM coupon_transaction_event WHERE event_key=? AND payment_id=? AND user_coupon_id=? AND kind='CONSUME'",Long.class,key,payment,a.get("user_coupon_id"))!=1L)throw conflict();return;}if(!"RESERVED".equals(a.get("state")))throw conflict();var o=db.one("SELECT * FROM `order` WHERE id=?",order);var p=CommissionLedger.payment(db,o,payment);if(instant(p.get("paid_at")).isBefore(instant(a.get("created_at")))||!instant(p.get("paid_at")).isBefore(instant(a.get("reserved_until")))||db.jdbc.queryForObject("SELECT COUNT(*) FROM payment_exception WHERE order_id=?",Long.class,order)>0||(!Set.of("PAID","RECEIVED","IN_SERVICE","PENDING_VERIFY","COMPLETED","DISPUTED").contains(o.get("status"))&&!("CLOSED".equals(o.get("status"))&&"REFUND_CANCELLED".equals(o.get("close_reason")))))throw conflict();if(db.jdbc.update("UPDATE user_coupon SET status='USED',reserved_until=NULL,used_at=? WHERE id=? AND status='RESERVED' AND order_id=?",p.get("paid_at"),a.get("user_coupon_id"),order)!=1)throw conflict();db.jdbc.update("UPDATE order_coupon_allocation SET state='CONSUMED',updated_at=? WHERE order_id=?",time(db.now()),order);event(db,number(a,"user_coupon_id"),"CONSUME",key,order,payment,null,null,"RESERVED","USED",CASH_RULE);}
 static void release(ReservationStore db,long order){var a=lockAllocation(db,order);if(a==null||"RELEASED".equals(a.get("state")))return;if(!"RESERVED".equals(a.get("state")))throw conflict();var o=db.one("SELECT * FROM `order` WHERE id=?",order);if(!"CLOSED".equals(o.get("status"))||!Set.of("PAYMENT_EXPIRED","OWNER_CANCELLED").contains(o.get("close_reason"))||db.jdbc.queryForObject("SELECT COUNT(*) FROM payment p JOIN payment_event e ON e.payment_id=p.id AND e.channel=p.channel WHERE p.order_id=? AND p.status='SUCCEEDED' AND e.outcome='PAID' AND p.is_deleted=0 AND e.is_deleted=0",Long.class,order)>0)throw conflict();if(db.jdbc.update("UPDATE user_coupon SET status='AVAILABLE',order_id=NULL,reserved_until=NULL,used_at=NULL WHERE id=? AND status='RESERVED' AND order_id=?",a.get("user_coupon_id"),order)!=1)throw conflict();db.jdbc.update("UPDATE order_coupon_allocation SET state='RELEASED',updated_at=? WHERE order_id=?",time(db.now()),order);event(db,number(a,"user_coupon_id"),"RELEASE","order:"+order+":release",order,null,null,null,"RESERVED","AVAILABLE",CASH_RULE);}
 static void returned(ReservationStore db,long order,long refund){var a=lockAllocation(db,order);if(a==null)return;String key="order:"+order+":refund-return";if("RETURNED".equals(a.get("state"))){if(db.jdbc.queryForObject("SELECT COUNT(*) FROM coupon_transaction_event WHERE event_key=? AND refund_id=? AND kind='REFUND_RETURN'",Long.class,key,refund)!=1L)throw conflict();return;}if(!"CONSUMED".equals(a.get("state")))throw conflict();var o=db.one("SELECT * FROM `order` WHERE id=?",order);var r=db.one("SELECT * FROM refund WHERE id=? AND order_id=? AND is_deleted=0 FOR UPDATE",refund,order);if(!"SUCCEEDED".equals(r.get("status"))||!"CLOSED".equals(o.get("status"))||!"REFUND_CANCELLED".equals(o.get("close_reason"))||r.get("owner_consented_at")==null||r.get("merchant_consented_at")==null||r.get("refunded_at")==null||((BigDecimal)r.get("amount")).compareTo((BigDecimal)a.get("cash_amount"))!=0||db.jdbc.queryForObject("SELECT COUNT(*) FROM refund_event WHERE refund_id=? AND outcome='SUCCEEDED' AND event_hash<>''",Long.class,refund)!=1L)throw conflict();CommissionLedger.payment(db,o,number(r,"payment_id"));if(db.jdbc.update("UPDATE user_coupon SET status='AVAILABLE',order_id=NULL,reserved_until=NULL,used_at=NULL WHERE id=? AND status='USED' AND order_id=?",a.get("user_coupon_id"),order)!=1)throw conflict();db.jdbc.update("UPDATE order_coupon_allocation SET state='RETURNED',updated_at=? WHERE order_id=?",time(db.now()),order);event(db,number(a,"user_coupon_id"),"REFUND_RETURN",key,order,number(r,"payment_id"),refund,null,"USED","AVAILABLE",CASH_RULE);}
 static Map<String,Object> summary(ReservationStore db,Map<String,Object> o){if(o.get("coupon_id")==null)return null;var a=allocation(db,number(o,"id"),false);if(a==null||!trustedOrder(db,o))return Map.of("state","UNKNOWN","source_known",false);var terms=db.parse(a.get("terms_json"));return Map.of("state",a.get("state"),"source_known",true,"user_coupon_id",a.get("user_coupon_id"),"coupon_id",a.get("coupon_id"),"name",terms.path("name").asText(),"original_amount",a.get("original_amount").toString(),"discount_amount",a.get("discount_amount").toString(),"cash_amount",a.get("cash_amount").toString(),"rule_version",a.get("rule_version"),"valid_to",terms.path("valid_to").asText());}
 static boolean commissionReady(ReservationStore db,Map<String,Object> o,Map<String,Object> p){if(o.get("coupon_id")==null)return true;var a=allocation(db,number(o,"id"),false);return trustedOrder(db,o)&&a!=null&&Set.of("CONSUMED","RETURNED").contains(a.get("state"))&&db.jdbc.queryForObject("SELECT COUNT(*) FROM coupon_transaction_event WHERE order_id=? AND user_coupon_id=? AND payment_id=? AND kind='CONSUME' AND rule_version=?",Long.class,o.get("id"),a.get("user_coupon_id"),p.get("id"),CASH_RULE)==1L;}
}
